  const present: { readonly item: T; readonly value: string | number }[] = [];
  const absent: T[] = [];
  for (const item of items) {
    const read = value(item);
    if (read === null || read === undefined) {
      absent.push(item);
    } else {
      present.push({ item, value: read });
    }
  }
  const sign = order === 'asc' ? 1 : -1;
  // `Array.prototype.sort` is stable, so equal values keep their loaded order in both directions.
  present.sort((a, b) => sign * compareSortValues(a.value, b.value, kind, enumOrder));
